    origin/main is a cached Git ref, not a fresh network query.
    """
    def read_ref(ref):
        try:
            return _version_or_none(_git_ok(["rev-parse", "--verify", ref]))
        except UpdateError:
            return None
    return {"success": True, "versions": {
